// Conformance harness for the port of ShellCheck (e11f964); no Haskell counterpart
//
// Regression guard: the conformance hooks run checks from the registry
// `shelllint_checks::CHECKS` (generated by crates/checks/build.rs). If a
// check went missing from it, it would read as `unported` instead of failing.
#![cfg(feature = "analyzer")]

use shelllint_conformance::runner::{Filter, run_all};
use shelllint_conformance::{default_corpus_dir, load_corpus};

#[test]
fn registry_lists_the_checks() {
    assert!(
        shelllint_checks::CHECKS.iter().any(|e| e.module == "Analytics.hs" && e.name == "checkEchoWc"),
        "Analytics.hs:checkEchoWc missing from shelllint_checks::CHECKS"
    );
}

#[test]
fn pilot_report_passes() {
    let recs = load_corpus(&default_corpus_dir().join("tests.jsonl")).unwrap();
    let f = Filter { target: Some("checkEchoWc".into()), ..Default::default() };
    let (c, _) = run_all(&recs, &f);
    assert_eq!((c.pass, c.fail, c.blocked, c.unported), (1, 0, 0, 0));
}
